		continue;
	}

	if (!data->bulk_rx_ep && usb_endpoint_is_bulk_in(ep_desc)) {
		if (!usb_pipe_type_check(udev, usb_rcvbulkpipe(udev, ep_desc->bEndpointAddress)))
			data->bulk_rx_ep = ep_desc;
		continue;
	}
}

